"""Final technical report in Markdown and PDF from frozen measured evidence."""
from pathlib import Path
import json,csv,html
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,Image,PageBreak
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.enums import TA_LEFT
ROOT=Path(__file__).resolve().parents[1]
def main():
 full=json.loads((ROOT/'reports/day9/movie1/verification.json').read_text());final=json.loads((ROOT/'reports/day9-final-verification.json').read_text());invalid=json.loads((ROOT/'reports/day9/invalid-input-results.json').read_text());cfg=json.loads((ROOT/'models/raw-v2.1/configuration.json').read_text());metrics=list(csv.DictReader((ROOT/'reports/day10/final-performance.csv').open()));assert full['status']==final['status']==invalid['status']=='PASS'
 a=full['audit'];identity=full['tracking_identity_audit'];sections=[]
 def add(title,text):sections.append((title,text))
 add('Project outcome','FlyAggression Analyzer Version 2.1 is a tested local research prototype supporting raw MP4 analysis and the original MATLAB feature workflow. The selected raw-video model, preprocessing and postprocessing remain frozen. Days 9 and 10 tested the complete software path and prepared a reproducible release. This is a research deliverable, not a certification of biological accuracy.')
 add('Frozen model and workflows','Raw MP4 → automatic arena calibration → pinned Caltech FlyTracker → 36-feature adapter → Version 2.1 Random Forest → event detection → counts, durations, frequencies, timelines and exports. Compatible original MATLAB features → original frozen Version 1.0 classifier → its original postprocessing. Training movies: 1–4. Development selection recording: movie5. No newly untouched final-test recording is available. Movies6–10 were previously examined and were not used for this final run or retuning.')
 add('Full-length MP4-to-report test',f"A fresh 30-minute movie1 MP4 was processed from automatic calibration through new tracking, feature extraction, frozen inference and report export. Calibration took {full['automatic_calibration_seconds']:.1f} seconds; tracking, conversion and prediction took {full['tracking_adapter_prediction_seconds']:.1f} seconds; total audited run took {full['total_seconds']:.1f} seconds ({full['total_seconds']/60:.2f} minutes). The result contained {a['full_grid_rows']:,} ordered fly-frame rows, {a['total_events']} predicted events and {a['total_fly_seconds']:.3f} summed fly-seconds in predicted lunges. This was a training-source functional test, not an independent accuracy evaluation. Runtime is a single measurement on this machine, not a guarantee for arbitrary uploads.")
 add('Quantification and export verification','The independent audit reconstructs inclusive event duration as (end−start+1)/30, onset as (start−1)/30 and exclusive stop as end/30. It checks event-to-frame membership, non-overlapping per-fly events, per-fly counts, summed durations, recording counts and per-fly-minute frequency denominators. CSV tables were read back, the PNG was decoded, and every ZIP member was checked byte-for-byte against its source export. Both source tracks retain consecutive frames 1–54,000. Event counts sum both source flies; simultaneous bouts can overlap in wall-clock time.')
 add('Regression and invalid-input testing',f"The final Version 2.1 regression suite passed {final['v21_test_count']} tests; the unchanged original-workflow suite passed {final['original_test_count']} tests. Nine real service-level invalid-input cases were handled: empty MP4, wrong extension, missing consent, missing calibration, invalid physical diameter, corrupted MP4, incompatible 15 fps MP4, corrupted calibration MAT and corrupted feature MAT. Missing or altered releases and model/configuration mismatches also have regression coverage. The original movie5 MATLAB example still produces 325 events using the original model hash. No unhandled failures occurred in the one valid full-run check and these nine rejected-input cases; this small test set does not estimate a population reliability rate.")
 add('Routing bug fixed','Known adapter-generated MAT files carry feat.integration_status. Version 2.1 now rejects those files in original-feature mode instead of silently applying the original classifier. Accepted original files still delegate to the unchanged original runtime. The guard cannot identify arbitrary externally generated features after provenance markers are stripped; numerical compatibility remains the user’s responsibility. The frozen original model, raw model, their configurations, adapter and automatic calibration sources were not modified.')
 add('Equivalent-condition development evaluation','Both frozen models were rerun on the exact same newly extracted movie5 feature file. Predictions were generated on the complete 108,000-row grid without annotations. Frame scoring then used the same 100,479 reliable mapped rows (527 positive frames); event scoring used the same 100,425 rows after whole-bout censoring, retaining 124 of 303 source bouts. IoU threshold was 0.3 and event matches were one-to-one. The newly generated probabilities reproduce the earlier frozen artifacts within 1e−14. No fitting, model selection or threshold tuning occurred during Days 9–10.')
 add('Interpreting the comparison','The selected Version 2.1 development result has frame F1 62.32% and event F1 75.63%, versus Version 2.0 operating on these same new features at 16.64% and 16.06%. Version 2.1 predicts 114 events against 124 retained expert bouts: 90 matched, 24 false positive and 34 missed. The net count difference of −10 hides both kinds of error. These gains include the lower selected threshold and tuned postprocessing; they are not a pure comparison of RF architecture. The Day 4 control at threshold 0.15 already achieved 60.73% frame F1. The original feature-based model’s previously reported 79.53% event F1 is a different feature/evaluation condition and must not be presented as raw-video accuracy.')
 add('Tracking and annotation limitations',f"The fresh movie1 audit found {identity['reliable_reference_mapping_frames']:,} frames with reliable correspondence to the supplied reference tracks and {identity['uncertain_reference_mapping_frames']:,} uncertain frames, {identity['pointwise_mapping_changes']} pointwise preferred-mapping changes and {identity['new_tracking_warning_frames']} new-track warning frames. Preferred-mapping changes are diagnostic signals, not certified counts of biological identity swaps. The software preserves source IDs and frame order but cannot guarantee that a source track always represents the same biological fly. For movie5, only 44.44% of annotation-reliable positive frames and 40.92% of source bouts were retained for evaluation; exclusions can bias performance upward. Negative frames are inferred under an exhaustive-annotation assumption. Production videos do not have expert labels available to recreate that censoring mask.")
 add('Calibration and video conditions','The supported target is an overhead, single circular arena with two flies at verified 30 fps. Physical diameter must be supplied; pixels alone cannot reveal millimetres. The benchmark uses published nominal 16 mm, not an independently measured per-recording value. Automatic calibration requires a sufficiently clear boundary and reliable two-fly samples. A ten-second prefix alone failed that guard, although its full source recording calibrated; the guard remains intact. Existing strict MATLAB frame-rate checks can reject nominal 30 fps encodings whose decoded value differs slightly. Short clips use whole-recording stream normalization and may differ from full recordings. Arbitrary arenas, camera views, species, scales, crowded scenes and other aggression classes are outside the validated scope.')
 add('Installation, release and demonstration','The release includes both trained model bundles, model-specific imputation and feature ordering, frozen settings, Python dependency pins, source application, tracker source/native Apple Silicon helpers with notices, examples, verified outputs, figures and checksums. Licensed MATLAB and a Python environment are not bundled. Follow INSTALLATION.md, create the documented Python 3.12 environment, run the package integrity check and Launch_Analyzer.command. The portable package uses port 8503; the workspace desktop launcher continues on port 8502. DEMONSTRATION.md provides a five-minute PRJ501 walkthrough and an honest performance explanation. Relocated-package testing uses the existing pinned environment; a clean dependency download/install on another machine was not performed.')
 add('What remains unresolved','Fresh independent recordings with measured arena dimensions and expert-confirmed identities are required before claiming generalization. Review excluded interaction intervals, segmentation, orientation and annotation correspondence before increasing model complexity. Validate on additional recording conditions and measure runtime across video lengths. No independent final-test performance or universal raw-video compatibility is claimed. The full-run, regression and export evidence establishes a tested research prototype within the documented local environment.')
 lines=['# FlyAggression Analyzer Version 2.1 — Final Project Progress Report','','PRJ 501 · 21 October 2026 · Days 1–10 completed for the documented research-prototype scope','']
 for title,text in sections:lines += ['## '+title,'',text,'']
 table=[['Model','Frame precision','Frame recall','Frame F1','Event precision','Event recall','Event F1']]
 for r in metrics:table.append([r['model']]+[f"{float(r[k]):.2%}" for k in ['frame_precision','frame_recall','frame_f1','event_precision','event_recall','event_f1']])
 lines += ['## Final movie5 performance table','','| '+' | '.join(table[0])+' |','|'+'|'.join(['---']*7)+'|']+['| '+' | '.join(row)+' |' for row in table[1:]]
 lines += ['','## Figures','','![Frame confusion matrices](reports/day10/frame-confusion-matrices.png)','','![Event timelines](reports/day10/movie5-event-timelines.png)','','## Inspectable evidence','','- reports/day9/movie1/verification.json: fresh full-run time, quantification and identity audit.','- reports/day9/invalid-input-results.json: nine real rejected-input cases.','- reports/day9-final-verification.json: final preservation and regression checks.','- reports/day10/final-performance.csv and frame-confusion-matrices.json: final metrics.','- reports/day10/Version-2.0 and Version-2.1: fresh frozen inference and event matching.','- models/raw-v2.1: frozen raw-specific bundle and settings.','- config/days5-7-protocol.json: development selection procedure.','- INSTALLATION.md and DEMONSTRATION.md: release use and PRJ501 demonstration.','',f"Raw model SHA-256: `{cfg['model_sha256']}`."]
 (ROOT/'FINAL-REPORT.md').write_text('\n'.join(lines)+'\n')
 styles=getSampleStyleSheet();styles.add(ParagraphStyle(name='Body21',fontName='Helvetica',fontSize=9.5,leading=13,spaceAfter=8,textColor=colors.HexColor('#243447')));styles.add(ParagraphStyle(name='Heading21',fontName='Helvetica-Bold',fontSize=13,leading=16,spaceBefore=10,spaceAfter=6,keepWithNext=True,textColor=colors.HexColor('#17456b')))
 story=[Paragraph('FlyAggression Analyzer 2.1',styles['Title']),Paragraph('Final Project Progress Report · PRJ 501',styles['Heading2']),Paragraph('21 October 2026 · Research prototype · Days 1–10',styles['Body21']),Spacer(1,12)]
 # Plain PDF standard fonts: map typographic math punctuation to supported glyphs.
 def clean(text):return text.replace('→',' to ').replace('−','-').replace('–','-').replace('’',"'").replace('×',' x ').replace('…','...')
 for i,(title,text) in enumerate(sections):
  story += [Paragraph(clean(title),styles['Heading21']),Paragraph(html.escape(clean(text)),styles['Body21'])]
  if title=='Equivalent-condition development evaluation':
   short=[['Model','Frame P','Frame R','Frame F1','Event P','Event R','Event F1']]+table[1:];t=Table(short,colWidths=[78]+[62]*6,repeatRows=1);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e8eff5')),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('FONTSIZE',(0,0),(-1,-1),9),('BOTTOMPADDING',(0,0),(-1,-1),8),('TOPPADDING',(0,0),(-1,-1),8),('LINEBELOW',(0,0),(-1,0),.7,colors.grey)]));story += [t,Spacer(1,12),Image(str(ROOT/'reports/day10/frame-confusion-matrices.png'),width=450,height=210)]
  if title=='Tracking and annotation limitations':story += [Image(str(ROOT/'reports/day10/movie5-event-timelines.png'),width=450,height=225),Spacer(1,8)]
 story += [Paragraph('Evidence and provenance',styles['Heading21']),Paragraph('Source measurements: final-performance.csv, full-run verification.json, invalid-input-results.json and day9-final-verification.json. Settings and raw model SHA-256 are saved with the release. Original model hash: 508f49002159bb6da8be4c42f38c76ba43215b692e96aa73276e287cedb86a42.',styles['Body21'])]
 def footer(c,doc):c.setFont('Helvetica',8);c.setFillColor(colors.grey);c.drawString(45,28,'FlyAggression Analyzer 2.1 · Development evidence, not independent final-test performance');c.drawRightString(550,28,str(doc.page))
 SimpleDocTemplate(str(ROOT/'FINAL-REPORT.pdf'),title='FlyAggression Analyzer 2.1 - Final Project Progress Report',pagesize=(595.28,841.89),rightMargin=45,leftMargin=45,topMargin=44,bottomMargin=45).build(story,onFirstPage=footer,onLaterPages=footer);print('Final Markdown and PDF reports created')
if __name__=='__main__':main()
